class Node:
    def __init__(self, val):
        self.val = val
        self.neighbors = []

def _clone_to_adjacency(start, count):
    result = [None] * count
    if start is None:
        return result
    seen = {id(start)}
    queue = [start]
    i = 0
    while i < len(queue):
        u = queue[i]
        i += 1
        result[u.val] = [v.val for v in u.neighbors]
        for v in u.neighbors:
            if id(v) not in seen:
                seen.add(id(v))
                queue.append(v)
    return result

def clone_check(adjacency, clone):
    original = [Node(i) for i in range(len(adjacency))]
    for i, row in enumerate(adjacency):
        for j in row:
            original[i].neighbors.append(original[j])
    originals = {id(n) for n in original}

    copy = clone(original[0] if original else None)
    if not original:
        return [] if copy is None else 'expected None for an empty graph'
    if copy is None:
        return 'returned None for a non-empty graph'

    by_value = {}
    seen = {id(copy)}
    queue = [copy]
    i = 0
    while i < len(queue):
        u = queue[i]
        i += 1
        if id(u) in originals:
            return f'not a deep copy: node {u.val} in the result is an original node'
        if not isinstance(u.val, int) or not 0 <= u.val < len(adjacency):
            return f'unexpected node value {u.val}'
        if u.val in by_value:
            return f'node {u.val} was copied more than once'
        by_value[u.val] = u
        for v in u.neighbors:
            if id(v) not in seen:
                seen.add(id(v))
                queue.append(v)

    if _clone_to_adjacency(original[0], len(adjacency)) != [list(row) for row in adjacency]:
        return 'the original graph was modified'
    return [row if row is not None else [] for row in _clone_to_adjacency(copy, len(adjacency))]

