public class Node
{
    public int Val;
    public List<Node> Neighbors = new List<Node>();
    public Node(int val) { Val = val; }
}
public static class CloneHarness
{
    private static int[][] ToAdjacency(Node? start, int count)
    {
        var result = new int[count][];
        if (start == null) return result;
        var seen = new HashSet<Node> { start };
        var queue = new Queue<Node>();
        queue.Enqueue(start);
        while (queue.Count > 0)
        {
            var u = queue.Dequeue();
            result[u.Val] = u.Neighbors.Select(v => v.Val).ToArray();
            foreach (var v in u.Neighbors) if (seen.Add(v)) queue.Enqueue(v);
        }
        return result;
    }

    public static object Run(int[][] adjacency, Func<Node?, Node?> clone)
    {
        var original = Enumerable.Range(0, adjacency.Length).Select(i => new Node(i)).ToArray();
        for (var i = 0; i < adjacency.Length; i++)
            foreach (var j in adjacency[i]) original[i].Neighbors.Add(original[j]);
        var originals = new HashSet<Node>(original);

        var copy = clone(original.Length > 0 ? original[0] : null);
        if (original.Length == 0) return copy == null ? (object)new int[0][] : "expected null for an empty graph";
        if (copy == null) return "returned null for a non-empty graph";

        var byValue = new Dictionary<int, Node>();
        var seen = new HashSet<Node> { copy };
        var queue = new Queue<Node>();
        queue.Enqueue(copy);
        while (queue.Count > 0)
        {
            var u = queue.Dequeue();
            if (originals.Contains(u)) return $"not a deep copy: node {u.Val} in the result is an original node";
            if (u.Val < 0 || u.Val >= adjacency.Length) return $"unexpected node value {u.Val}";
            if (byValue.ContainsKey(u.Val)) return $"node {u.Val} was copied more than once";
            byValue[u.Val] = u;
            foreach (var v in u.Neighbors) if (seen.Add(v)) queue.Enqueue(v);
        }

        var before = ToAdjacency(original[0], adjacency.Length);
        for (var i = 0; i < adjacency.Length; i++)
            if (before[i] == null || !before[i].SequenceEqual(adjacency[i])) return "the original graph was modified";
        return ToAdjacency(copy, adjacency.Length).Select(row => row ?? new int[0]).ToArray();
    }
}

